package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A plan date a plan has made its claim for. */
@Entity
@Table(name = "plan_claim")
public class PlanClaim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "plan_id", nullable = false)
    private Long planId;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    protected PlanClaim() {
    }

    public PlanClaim(Long planId, LocalDate date, Long claimId) {
        this.planId = planId;
        this.date = date;
        this.claimId = claimId;
    }

    public Long getId() {
        return id;
    }

    public Long getPlanId() {
        return planId;
    }

    public LocalDate getDate() {
        return date;
    }

    public Long getClaimId() {
        return claimId;
    }
}
package net.officefloor.hq.app.plan;

import java.util.Collection;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PlanClaimRepository extends JpaRepository<PlanClaim, Long> {

    List<PlanClaim> findByPlanIdInOrderByIdAsc(Collection<Long> planIds);
}
package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The plans on a sheet. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class PlanController {

    /** A plan as the screen shows it, with how many claims it has made so far and its next dates after the
     *  sheet's today. */
    public record PlanView(long id, long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated, List<LocalDate> nextDates) {

        public static PlanView of(PlanService.Counted c) {
            Plan p = c.plan();
            return new PlanView(p.getId(), p.getPersonId(), p.getAmount().toPlainString(), p.getStart(), p.getEvery(),
                    p.getDay(), p.getEnd(), c.generated(), c.nextDates());
        }
    }

    /** A plan as the form submits it, with either an interval or a day of the month; a missing start takes the
     *  sheet's today. */
    public record PlanForm(@NotNull BigDecimal amount, LocalDate start, Integer every, Integer day,
            @NotNull LocalDate end) {
    }

    /** What a generate did: how many claims it made, the claims in the order made, and the sheet's plans. */
    public record GeneratedView(int made, List<ClaimView> claims, List<PlanView> plans) {
    }

    private final PlanService plans;

    public PlanController(PlanService plans) {
        this.plans = plans;
    }

    @GetMapping("/plans")
    public List<PlanView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return plans.list(sheetId).stream().map(PlanView::of).toList();
    }

    @PostMapping("/people/{personId}/plans")
    public PlanView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PlanForm request) {
        return PlanView.of(plans.add(sheetId, user, personId, request.amount(), request.start(), request.every(),
                request.day(), request.end()));
    }

    @PostMapping("/plans/generate")
    public GeneratedView generate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        PlanService.Generated done = plans.generate(sheetId, user);
        return new GeneratedView(done.claims().size(), done.claims().stream().map(ClaimView::of).toList(),
                done.plans().stream().map(PlanView::of).toList());
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** A person's plan on a sheet: an amount claimed on its start date and every so many days after, or instead monthly
 *  on a day of the month from the start's month, up to its end date. */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** Days between plan dates; empty for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) a monthly plan falls on; empty for a plan that runs every so many days. */
    @Column(name = "month_day")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    protected Plan() {
    }

    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    /** The plan's dates from its start up to and including {@code last}, in order. A monthly plan falls on its day
     *  in every month from the start's month, on the month's last day when the day is beyond its length, leaving
     *  out dates before the start. */
    public List<LocalDate> datesUpTo(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
                dates.add(d);
            }
            return dates;
        }
        for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
            LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
            if (!d.isBefore(start) && !d.isAfter(last)) {
                dates.add(d);
            }
        }
        return dates;
    }

    /** The plan's first {@code count} dates after {@code after} and on or before its end, in order. */
    public List<LocalDate> nextDates(LocalDate after, int count) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            LocalDate d = start;
            if (d.isBefore(after)) {
                long steps = (after.toEpochDay() - start.toEpochDay()) / every;
                d = start.plusDays(steps * every);
            }
            for (; !d.isAfter(end) && dates.size() < count; d = d.plusDays(every)) {
                if (d.isAfter(after)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        YearMonth m = YearMonth.from(start.isAfter(after) ? start : after);
        for (; !m.atDay(1).isAfter(end) && dates.size() < count; m = m.plusMonths(1)) {
            LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
            if (!d.isBefore(start) && d.isAfter(after) && !d.isAfter(end)) {
                dates.add(d);
            }
        }
        return dates;
    }

    public LocalDate getEnd() {
        return end;
    }

